(()=>{const old=document.querySelector('#esc-about');if(!old||document.querySelector('.urvion-about-stage'))return;old.id='esc-about-original';const s=document.createElement('section');s.id='esc-about';s.className='urvion-about-stage';s.innerHTML=`<div class="urvion-about-media"><video muted loop playsinline preload="metadata" poster="assets/images/esc-pirate-cove.webp"><source src="assets/videos/HH.mp4" type="video/mp4"></video><i></i></div><div class="urvion-about-sticky"><article class="urvion-about-panel"><p class="about-label"><b>CHAPTER 01</b> THE CREW BEHIND THE CAUSE</p><img class="about-logo" src="assets/images/eco-social-club-logo-transparent.png" alt="Eco Social Club"><h2>NOT ALL TREASURE<br><em>IS GOLD.</em></h2><div class="about-copy"><p>The Eco-Social Club (ESC) of Silicon University, Odisha is a student-led initiative committed to environmental sustainability, social responsibility and individual well-being.</p><p>Across <strong>Ecology, Social Welfare and Zeal,</strong> students turn ideas into meaningful action through awareness, outreach and community initiatives.</p></div></article><article class="urvion-about-panel"><p class="about-label"><b>CHAPTER 02</b> THE INNOVATION ARENA</p><h2>THE <em>IMPACT</em><br>WE BUILD.</h2><div class="about-metrics"><span><strong>500+</strong><small>REGISTERED MEMBERS</small></span><span><strong>400+</strong><small>URVION PARTICIPANTS</small></span><span><strong>03</strong><small>CORE DOMAINS</small></span></div></article><article class="urvion-about-panel"><p class="about-label"><b>CHAPTER 03</b> THE CALL TO ACTION</p><h2>READY TO<br><em>SET SAIL?</em></h2><blockquote>“Every lasting voyage begins when a community chooses to care.”</blockquote><p class="about-note">URVION 2.0 — The Pirates of Carebian — is our next horizon for innovation, collaboration and collective impact.</p><a href="events.html">EXPLORE THE FOUR EXPEDITIONS ↗</a></article><p class="about-cue">/// SCROLL TO TURN THE CHAPTER ↓</p></div>`;old.before(s);const v=s.querySelector('video'),panels=[...s.querySelectorAll('.urvion-about-panel')],reduce=matchMedia('(prefers-reduced-motion:reduce)');let raf=0;function draw(){raf=0;const r=s.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/Math.max(1,s.offsetHeight-innerHeight)))*2;panels.forEach((el,i)=>{const d=i-p;el.style.opacity=Math.max(0,1-Math.abs(d)*1.25);el.style.transform=reduce.matches?'none':`translate3d(0,${d*12}vh,0)`;el.classList.toggle('is-active',i===Math.round(p))})}function go(){if(!raf)raf=requestAnimationFrame(draw)}new IntersectionObserver(e=>{e[0].isIntersecting&&!reduce.matches?v.play().catch(()=>{}):v.pause();go()},{threshold:.03}).observe(s);addEventListener('scroll',go,{passive:true});addEventListener('resize',go,{passive:true});reduce.addEventListener('change',go);draw()})();
